"""Company website adapter (highest-trust source).

Finds candidate pages from the homepage nav, common paths, and sitemap.xml, ranks them by
URL keywords, and fetches the top MAX_PAGES. No LLM here.
"""

from __future__ import annotations

import logging
import re
from dataclasses import dataclass
from urllib.parse import urljoin, urlsplit, urlunsplit

from selectolax.lexbor import LexborHTMLParser as HTMLParser

from leadership.sources.base import AdapterReport, Company, RawDocument
from leadership.sources.fetch import FetchBlocked, Fetcher, html_to_text

log = logging.getLogger(__name__)

SOURCE_TYPE = "company_site"
NAMESPACE = "company_site"
MAX_PAGES = 60
MAX_CHILD_SITEMAPS = 6

COMMON_PATHS = (
    "about", "about-us", "team", "our-team", "leadership", "company", "company/leadership",
    "management", "people", "press", "newsroom", "careers",
)  # fmt: skip

# Path keywords and the score they give a URL. Highest match wins.
_LEADERSHIP_WORDS = r"leadership|team|about|management|executives?|founders?|people|company"
_PEOPLE_NEWS_WORDS = (
    r"appoint|names?|named|joins?|hires?|welcome|chief|officer|president|vp|vice-president|"
    r"head-of|executive|leader|founder|ceo|cto|cfo|coo|cmo|cpo|board"
)
_NEWS_WORDS = r"press|news|newsroom|blog|announce|media"
# Child sitemaps worth opening; product catalogs (stocks, crypto, help center) are not.
_SITEMAP_KEEP = r"newsroom|press|news|blog|company|about|marketing|pages?|main|post"


@dataclass
class Candidate:
    url: str
    score: int
    lastmod: str = ""
    via: str = ""


def _clean(url: str) -> str:
    parts = urlsplit(url)
    path = parts.path or "/"
    return urlunsplit((parts.scheme, parts.netloc.lower(), path, "", ""))


def score_url(url: str) -> int:
    path = urlsplit(url).path.lower()
    segments = [s for s in path.split("/") if s]
    last = segments[-1] if segments else ""
    if any(re.fullmatch(_LEADERSHIP_WORDS, s) for s in segments):
        return 10
    is_news = any(re.search(_NEWS_WORDS, s) for s in segments)
    if is_news and re.search(rf"(^|-)({_PEOPLE_NEWS_WORDS})(-|$)", last):
        return 8
    if re.search(rf"(^|-)({_LEADERSHIP_WORDS})(-|$)", last):
        return 6
    if "careers" in segments or "jobs" in segments:
        return 3
    if is_news and len(segments) >= 2:
        return 2  # an individual post: bylines often carry author titles
    return 0


def _site_hosts(company: Company) -> set[str]:
    hosts = {urlsplit(company.site_url).hostname or "", company.domain}
    return {h.removeprefix("www.") for h in hosts if h}


def _on_site(url: str, hosts: set[str]) -> bool:
    host = (urlsplit(url).hostname or "").removeprefix("www.")
    return any(host == h or host.endswith("." + h) for h in hosts)


def parse_sitemap(xml: str) -> tuple[list[tuple[str, str]], list[str]]:
    """Return ([(url, lastmod)], [child sitemap urls]). Regex, not an XML parser, on purpose:
    sitemaps are simple, and this avoids entity-expansion risks on untrusted XML."""
    urls = []
    for block in re.findall(r"<url>(.*?)</url>", xml, flags=re.S):
        loc = re.search(r"<loc>\s*(.*?)\s*</loc>", block, flags=re.S)
        mod = re.search(r"<lastmod>\s*(.*?)\s*</lastmod>", block, flags=re.S)
        if loc:
            urls.append((loc.group(1).replace("&amp;", "&"), mod.group(1) if mod else ""))
    children = []
    for block in re.findall(r"<sitemap>(.*?)</sitemap>", xml, flags=re.S):
        loc = re.search(r"<loc>\s*(.*?)\s*</loc>", block, flags=re.S)
        if loc:
            children.append(loc.group(1).replace("&amp;", "&"))
    return urls, children


def _locale_prefix(site_url: str) -> str:
    """'/us/en/' for https://robinhood.com/us/en/, else '/'."""
    path = urlsplit(site_url).path
    return path if re.fullmatch(r"/[a-z]{2}/[a-z]{2}/", path) else "/"


class CompanySiteAdapter:
    source_type = SOURCE_TYPE

    def __init__(self, fetcher: Fetcher, max_pages: int = MAX_PAGES) -> None:
        self.fetcher = fetcher
        self.max_pages = max_pages

    def _get(self, url: str, report: AdapterReport):
        try:
            res = self.fetcher.get(url, NAMESPACE)
        except FetchBlocked as exc:
            report.skip(url, str(exc))
            return None
        if not res.ok:
            report.skip(url, f"HTTP {res.status}" if res.status else "network error")
            return None
        return res

    def candidates(self, company: Company, report: AdapterReport) -> list[Candidate]:
        hosts = _site_hosts(company)
        root = f"{urlsplit(company.site_url).scheme}://{urlsplit(company.site_url).netloc}"
        found: dict[str, Candidate] = {}

        def add(url: str, via: str, lastmod: str = "", score: int | None = None) -> None:
            url = _clean(url)
            if not url.startswith("http") or not _on_site(url, hosts):
                return
            s = score_url(url) if score is None else score
            prev = found.get(url)
            if prev is None or s > prev.score:
                found[url] = Candidate(url, s, lastmod or (prev.lastmod if prev else ""), via)
            elif lastmod and not prev.lastmod:
                prev.lastmod = lastmod

        add(company.site_url, "homepage", score=9)
        prefixes = {"/", _locale_prefix(company.site_url)}
        for prefix in prefixes:
            for path in COMMON_PATHS:
                add(urljoin(root, prefix + path), "common_path")

        home = self._get(company.site_url, report)
        if home is not None:
            for a in HTMLParser(home.text_body()).css("a[href]"):
                add(urljoin(home.final_url, a.attributes.get("href") or ""), "nav")

        sitemap_urls = [*self.fetcher.sitemaps_for(root), urljoin(root, "/sitemap.xml")]
        sitemap_urls = list(dict.fromkeys(sitemap_urls))
        children_opened = 0
        queue = list(sitemap_urls)
        while queue:
            sm_url = queue.pop(0)
            if sm_url.endswith(".gz"):
                report.notes.append(f"skipped gzipped sitemap {sm_url}")
                continue
            res = self._get(sm_url, report)
            if res is None:
                continue
            urls, children = parse_sitemap(res.text_body())
            for url, lastmod in urls:
                add(url, "sitemap", lastmod)
            for child in children:
                if re.search(_SITEMAP_KEEP, child.lower()) and children_opened < MAX_CHILD_SITEMAPS:
                    if _on_site(child, hosts):
                        queue.append(child)
                        children_opened += 1
                else:
                    report.notes.append(f"skipped child sitemap {child}")

        ranked = sorted(
            (c for c in found.values() if c.score > 0),
            key=lambda c: (-c.score, _neg_date(c.lastmod), c.url),
        )
        dropped = len(ranked) - self.max_pages
        if dropped > 0:
            report.notes.append(f"{dropped} lower-ranked candidate URLs not fetched (cap)")
        return ranked[: self.max_pages]

    def discover(self, company: Company) -> AdapterReport:
        report = AdapterReport(SOURCE_TYPE)
        seen_final: set[str] = set()
        for cand in self.candidates(company, report):
            res = self._get(cand.url, report)
            if res is None:
                continue
            final = _clean(res.final_url)
            if final in seen_final:
                continue  # e.g. /about redirecting to the homepage
            seen_final.add(final)
            if "html" not in res.content_type:
                report.skip(cand.url, f"not HTML ({res.content_type or 'unknown type'})")
                continue
            text, title = html_to_text(res.text_body())
            if len(text) < 200:
                report.skip(cand.url, "almost no text (soft 404, or rendered by JavaScript)")
                continue
            raw_path = self.fetcher.write_text(NAMESPACE, cand.url, text)
            report.documents.append(
                RawDocument(
                    url=final,
                    source_type=SOURCE_TYPE,
                    title=title,
                    text=text,
                    fetched_at=res.fetched_at,
                    raw_path=raw_path,
                    meta={"score": cand.score, "via": cand.via, "lastmod": cand.lastmod},
                )
            )
        return report


def _neg_date(lastmod: str) -> str:
    # Sort newest first with an ascending sort: invert digits of an ISO date prefix.
    digits = re.sub(r"\D", "", lastmod)[:8].ljust(8, "0")
    return "".join(str(9 - int(d)) for d in digits)

"""SEC EDGAR adapter (public companies only; authoritative for executive officers).

Uses the free official endpoints with the SEC-required User-Agent (SEC_USER_AGENT):
- company_tickers.json to map ticker or name to CIK,
- the submissions API to find the latest 10-K and DEF 14A,
- the filing's primary document from the Archives.
"""

from __future__ import annotations

import json
import logging
import re

from leadership.config import require_setting
from leadership.sources.base import AdapterReport, Company, RawDocument
from leadership.sources.fetch import FetchBlocked, Fetcher, html_to_text

log = logging.getLogger(__name__)

SOURCE_TYPE = "sec_filing"
NAMESPACE = "sec_filing"
TICKERS_URL = "https://www.sec.gov/files/company_tickers.json"
SUBMISSIONS_URL = "https://data.sec.gov/submissions/CIK{cik}.json"
ARCHIVE_URL = "https://www.sec.gov/Archives/edgar/data/{cik}/{accession}/{document}"
FORMS = ("10-K", "DEF 14A")


def _sec_get(fetcher: Fetcher, url: str):
    return fetcher.get(url, NAMESPACE, user_agent=require_setting("SEC_USER_AGENT"))


def _norm(text: str) -> str:
    return re.sub(r"[^a-z0-9 ]", "", text.lower()).strip()


def lookup_cik(fetcher: Fetcher, name: str, ticker: str | None) -> tuple[str, str, str] | None:
    """Return (cik, ticker, sec_title) or None.

    With a ticker, match it exactly. Without one, accept a name match only if exactly one SEC
    registrant's title starts with the company name as a whole word: a generic name
    ("Campfire") must not latch onto an unrelated registrant. Pass --ticker to be explicit.
    """
    res = _sec_get(fetcher, TICKERS_URL)
    if not res.ok:
        raise RuntimeError(f"SEC ticker list unavailable (HTTP {res.status})")
    rows = json.loads(res.text_body()).values()
    if ticker:
        hits = [r for r in rows if r["ticker"].upper() == ticker.upper()]
    else:
        key = _norm(name)
        hits = [r for r in rows if re.match(rf"{re.escape(key)}\b", _norm(r["title"]))]
        if len({r["cik_str"] for r in hits}) != 1:
            if hits:
                titles = sorted({r["title"] for r in hits})[:5]
                log.info("SEC name match for %r is ambiguous (%s); private", name, titles)
            return None
    if not hits:
        return None
    row = hits[0]
    return str(row["cik_str"]).zfill(10), row["ticker"], row["title"]


EXEC_HEADING = (
    r"^(information about (our )?)?executive officers( of the registrant| of the company)?\.?$"
)


def find_section(text: str, heading_pattern: str = EXEC_HEADING, max_len: int = 20_000):
    """Character span of the executive-officers section, or None.

    Headings appear several times (table of contents, page headers, exhibit index), so pick
    the heading followed by the most title lines (lines ending in "Officer") before the next
    heading or 3,000 characters. Only a hint for pre-filtering: extraction still sees, and
    is checked against, the full text.
    """
    matches = list(re.finditer(heading_pattern, text, flags=re.I | re.M))
    best: tuple[int, int] | None = None
    for i, m in enumerate(matches):
        end = m.end() + 3000
        if i + 1 < len(matches):
            end = min(end, matches[i + 1].start())
        score = len(re.findall(r"\bOfficer,?$", text[m.end() : end], flags=re.M))
        if score and (best is None or score >= best[1]):  # ties: later wins (body after TOC)
            best = (m.start(), score)
    if best is None:
        return None
    return best[0], min(len(text), best[0] + max_len)


class SecEdgarAdapter:
    source_type = SOURCE_TYPE

    def __init__(self, fetcher: Fetcher) -> None:
        self.fetcher = fetcher

    def discover(self, company: Company) -> AdapterReport:
        report = AdapterReport(SOURCE_TYPE)
        if not company.is_public or not company.cik:
            report.notes.append("not a public company (no SEC registrant matched); skipped")
            return report
        url = SUBMISSIONS_URL.format(cik=company.cik)
        try:
            sub = _sec_get(self.fetcher, url)
        except FetchBlocked as exc:
            report.skip(url, str(exc))
            return report
        if not sub.ok:
            report.skip(url, f"HTTP {sub.status}")
            return report
        recent = json.loads(sub.text_body())["filings"]["recent"]
        latest: dict[str, int] = {}
        for i, form in enumerate(recent["form"]):
            if form in FORMS and form not in latest:
                latest[form] = i  # `recent` is newest first
        for form in FORMS:
            if form not in latest:
                report.notes.append(f"no {form} in recent filings")
                continue
            i = latest[form]
            doc_url = ARCHIVE_URL.format(
                cik=int(company.cik),
                accession=recent["accessionNumber"][i].replace("-", ""),
                document=recent["primaryDocument"][i],
            )
            try:
                res = _sec_get(self.fetcher, doc_url)
            except FetchBlocked as exc:
                report.skip(doc_url, str(exc))
                continue
            if not res.ok:
                report.skip(doc_url, f"HTTP {res.status}")
                continue
            text, _ = html_to_text(res.text_body())
            raw_path = self.fetcher.write_text(NAMESPACE, doc_url, text)
            span = find_section(text)
            if span is None:
                report.notes.append(f"{form}: no executive officers section found")
            report.documents.append(
                RawDocument(
                    url=doc_url,
                    source_type=SOURCE_TYPE,
                    title=f"{company.name} {form} filed {recent['filingDate'][i]}",
                    text=text,
                    fetched_at=res.fetched_at,
                    raw_path=raw_path,
                    meta={
                        "form": form,
                        "filing_date": recent["filingDate"][i],
                        "report_date": recent["reportDate"][i],
                        "executive_officers_span": span,
                    },
                )
            )
        return report

"""Step 1 of collection: resolve the company and run every source adapter. No LLM."""

from __future__ import annotations

import json
import logging
import re
from dataclasses import asdict, dataclass, field
from urllib.parse import urlsplit

from selectolax.lexbor import LexborHTMLParser as HTMLParser

from leadership.config import company_dir
from leadership.models import SOURCE_PRIORITY, utc_now_iso
from leadership.sources.base import AdapterReport, Company, RawDocument
from leadership.sources.company_site import CompanySiteAdapter
from leadership.sources.fetch import Fetcher
from leadership.sources.search import SearchAdapter
from leadership.sources.sec_edgar import SecEdgarAdapter, lookup_cik

log = logging.getLogger(__name__)


def normalize_domain(url_or_domain: str) -> str:
    text = url_or_domain.strip()
    if "://" not in text:
        text = "https://" + text
    host = (urlsplit(text).hostname or "").lower().removeprefix("www.")
    if not host or "." not in host:
        raise ValueError(f"Not a domain or URL: {url_or_domain!r}")
    return host


def site_name_from_html(html: str) -> str | None:
    tree = HTMLParser(html)
    og = tree.css_first('meta[property="og:site_name"]')
    if og and (og.attributes.get("content") or "").strip():
        return og.attributes["content"].strip()
    title = tree.css_first("title")
    if title:
        first = re.split(r"\s+[|:\-–—]\s+|:\s", title.text(strip=True))[0].strip()
        return first or None
    return None


def fetcher_for(domain: str, refresh: bool = False) -> Fetcher:
    return Fetcher(company_dir(domain) / "raw", refresh=refresh)


def resolve_company(
    fetcher: Fetcher,
    url_or_domain: str,
    name: str | None = None,
    ticker: str | None = None,
    private: bool = False,
) -> Company:
    domain = normalize_domain(url_or_domain)
    home = fetcher.get(f"https://{domain}/", "company_site")
    if not home.ok:
        raise RuntimeError(f"Homepage https://{domain}/ returned HTTP {home.status}")
    site_url = home.final_url
    name = name or site_name_from_html(home.text_body()) or domain.split(".")[0].title()
    company = Company(name=name, domain=domain, site_url=site_url)
    if not private:
        match = lookup_cik(fetcher, name, ticker)
        if match:
            company.cik, company.ticker, sec_title = match
            company.is_public = True
            log.info("SEC registrant: %s (%s, CIK %s)", sec_title, company.ticker, company.cik)
        elif ticker:
            raise RuntimeError(f"Ticker {ticker!r} not found in SEC company_tickers.json")
    return company


@dataclass
class DiscoveryResult:
    company: Company
    documents: list[RawDocument]
    reports: list[AdapterReport]
    stats: dict = field(default_factory=dict)


def discover(company: Company, fetcher: Fetcher, sources: tuple[str, ...] | None = None):
    adapters = [CompanySiteAdapter(fetcher), SecEdgarAdapter(fetcher), SearchAdapter(fetcher)]
    if sources:
        adapters = [a for a in adapters if a.source_type in sources]
    reports = [a.discover(company) for a in adapters]

    # One document per URL; the higher-priority source keeps it.
    by_url: dict[str, RawDocument] = {}
    for report in sorted(reports, key=lambda r: SOURCE_PRIORITY[r.source_type]):
        for doc in report.documents:
            by_url.setdefault(doc.url, doc)
    documents = list(by_url.values())

    search = next((a for a in adapters if isinstance(a, SearchAdapter)), None)
    stats = {
        "documents_by_source": {
            r.source_type: sum(d.source_type == r.source_type for d in documents) for r in reports
        },
        "skipped_by_source": {r.source_type: len(r.skipped) for r in reports},
        "network_requests": fetcher.network_requests,
        "search_api_calls": search.api_calls if search else 0,
    }
    result = DiscoveryResult(company, documents, reports, stats)
    write_manifest(result)
    return result


def write_manifest(result: DiscoveryResult) -> None:
    """Human-readable record of what discovery found and skipped (committed with the data)."""
    path = company_dir(result.company.domain) / "raw" / "manifest.json"
    manifest = {
        "generated_at": utc_now_iso(),
        "company": asdict(result.company),
        "stats": result.stats,
        "documents": [
            {k: v for k, v in asdict(d).items() if k != "text"} | {"chars": len(d.text)}
            for d in result.documents
        ],
        "skipped": {r.source_type: r.skipped for r in result.reports},
        "notes": {r.source_type: r.notes for r in result.reports},
    }
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(manifest, indent=2, ensure_ascii=False), encoding="utf-8")

